create table chat_room(id bigint auto_increment primary key,name varchar(120) not null,description varchar(1000) not null,category varchar(60) not null,department_id bigint not null,owner_id bigint not null,visibility varchar(20) not null,status varchar(20) not null,capacity int not null,version bigint not null,generation bigint not null,created_at timestamp(6) not null,foreign key(department_id) references department(id),foreign key(owner_id) references account(id));
create table room_member(id bigint auto_increment primary key,room_id bigint not null,account_id bigint not null,status varchar(20) not null,joined_at timestamp(6) not null,unique(room_id,account_id),foreign key(room_id) references chat_room(id),foreign key(account_id) references account(id));
create table chat_message(id bigint auto_increment primary key,room_id bigint not null,author_id bigint not null,content varchar(4000) not null,nonce varchar(40) not null,removed boolean not null,created_at timestamp(6) not null,unique(room_id,author_id,nonce),foreign key(room_id) references chat_room(id),foreign key(author_id) references account(id));
create index message_history on chat_message(room_id,id);
create table room_invite(id bigint auto_increment primary key,room_id bigint not null,created_by bigint not null,token_hash varchar(64) not null unique,expires_at timestamp(6) not null,max_uses int not null,uses int not null,revoked boolean not null,foreign key(room_id) references chat_room(id),foreign key(created_by) references account(id));
create table voice_lease(id bigint auto_increment primary key,room_id bigint not null,account_id bigint not null,identity varchar(80) not null unique,physical_room varchar(80) not null,credential varchar(64) not null,session_key varchar(64) not null,revoked boolean not null,expires_at timestamp(6) not null,foreign key(room_id) references chat_room(id),foreign key(account_id) references account(id));
